# 🗣 開口練習（對話台詞 → 提示＋另外兩種說法）
# 📷 單字小截圖（選填，之後每天照這個做）：tools/crops.py 依下面的設定產生 img/<id>/w/<單字id>.webp（長邊 ≤480px、WebP q≈70、每張 ≤30KB），
# 在單字那一列右邊顯示（先模糊，顯示文字後才清楚；點一下放大）。
#   crops：{單字 ja: (照片檔名, (x0, y0, x1, y1)[, 'fallback'])}，座標是相對照片寬高 0～1 的框（只框文字，程式會自動加邊）；
#          照片裡找不到那個字時，框一塊相關的地方並加 'fallback'（畫面上會標「相關畫面」）。沒寫的單字就沒有小截圖。
#   orig： {照片檔名: 原始照片路徑}（為了清楚，從原檔裁；原檔不進 repo；找不到原檔就用 img/<id>/ 裡壓縮過的照片）
#   blur： {照片檔名: [框, …]}  要打馬賽克的地方（姓名、條碼、票號、房號、座位號碼…），裁圖時一定會先蓋掉。
